import java.util.Arrays;

public class StronglyConnectedComponents {
    public static int stronglyConnectedComponents(int[][] graph) {
        int n = graph.length;
        int[] disc = new int[n];
        int[] low = new int[n];
        int[] st = new int[n];
        int time = 0;
        int scc = 0;
        for (int i = 0; i < n; i++) {
            if (disc[i] == 0) {
                dfs_loop(graph, i, disc, low, st, time, scc);
            }
        }
        return scc;
    }

    private static void dfs_loop(int[][] graph, int node, int[] disc, int[] low, int[] st, int time, int scc) {
        disc[node] = low[node] = ++time;
        st[node] = time;
        for (int neighbor : graph[node]) {
            if (disc[neighbor] == 0) {
                dfs_loop(graph, neighbor, disc, low, st, time, scc);
                low[node] = Math.min(low[node], low[neighbor]);
            } else if (st[neighbor] < st[node]) {
                low[node] = Math.min(low[node], disc[neighbor]);
            }
        }
        if (low[node] == disc[node]) {
            scc++;
            while (st[node] > 0) {
                int child = Arrays.asList(st).indexOf(st[node]);
                st[node] = -1;
                node = child;
            }
        }
    }
}
