public int shortestPath(boolean[][] maze, int startRow, int startCol) {
    if (!maze[startRow][startCol]) {
        return -1;
    }
    int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    int[][] memo = new int[maze.length][maze[0].length];
    for (int i = 0; i < memo.length; i++) {
        Arrays.fill(memo[i], -1);
    }
    int result = shortestPathHelper(maze, startRow, startCol, memo);
    return result == -1 ? -1 : result + 1;
}

private int shortestPathHelper(boolean[][] maze, int row, int col, int[][] memo) {
    if (row < 0 || col < 0 || row >= maze.length || col >= maze[0].length || !maze[row][col]) {
        return -1;
    }
    if (memo[row][col] != -1) {
        return memo[row][col];
    }
    int minPath = Integer.MAX_VALUE;
    for (int[] direction : directions) {
        int newRow = row + direction[0];
        int newCol = col + direction[1];
        int path = shortestPathHelper(maze, newRow, newCol, memo);
        if (path != -1 && path < minPath) {
            minPath = path;
        }
    }
    memo[row][col] = minPath;
    return minPath == Integer.MAX_VALUE ? -1 : minPath + 1;
}
