public static double calculateProbability(int n) {
    if (n == 1) {
        return 1.0; // The last passenger will always sit in their own seat, if there is only one passenger.
    } else if (n > 1) {
        // Calculate the number of possible seat assignments for n passengers.
        int numberOfPossibleSeatAssignments = factorial(n) / factorial(n - 1);

        // Calculate the number of seat assignments where the last passenger doesn't sit in their own seat.
        int numberOfInvalidSeatAssignments = numberOfPossibleSeatAssignments - 1;

        // Calculate the probability of the last passenger sitting in their own seat.
        double probability = (double) numberOfInvalidSeatAssignments / numberOfPossibleSeatAssignments;

        return 1 - probability; // The probability that the last passenger will sit in their own seat is 1 - the probability that they won't.
    } else {
        throw new IllegalArgumentException("Invalid input: n must be a positive integer.");
    }
}

private static int factorial(int x) {
    if (x <= 1) {
        return 1;
    } else {
        return x * factorial(x - 1);
    }
